-- Source and independent-solution verification; no historical scores changed.
-- Before-images are retained in audit_log; rows in active exams are deferred.
DO $review$
DECLARE v jsonb; q public.questions%rowtype; k public.question_keys%rowtype; a jsonb; f jsonb; patch jsonb;
BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "7dde08b9-caeb-5620-a1c4-5f141edab444", "source": "ACT 61C Practice, original 2008/09 mathematics test Q59, physical p9; https://www.mymathscloud.com/api/download/modules/University/SAT-ACT/ACT/2008-09.pdf?id=163821380", "review_note": "Recovered all five original graphs. The old textual figure descriptions misplaced the origin and asymptotes; those descriptions have been removed.", "explanation": "An odd function has a graph unchanged by a 180° rotation about the origin: every point (x,y) is paired with (−x,−y). Only graph E has this origin symmetry. A and B are symmetric about the y-axis, D is a line that does not pass through the origin, and C has an offset vertical asymptote, so it is not symmetric about the origin.", "correct": "E", "release": true, "before": {"stem": "A function f is an odd function if and only if f(−x) = −f(x) for every value of x in the domain of f. One of the functions graphed in the standard (x, y) coordinate plane is an odd function. Which one?\n[Figures: A: even W-shaped curve symmetric about the y-axis; B: V-shaped graph (vertex below origin, symmetric about y-axis); C: curve in QI and QIII like y = 1/x; D: line through the origin with positive slope; E: cubic-like curve not through the origin.]", "choices": [{"key": "A", "text": "Graph A"}, {"key": "B", "text": "Graph B"}, {"key": "C", "text": "Graph C"}, {"key": "D", "text": "Graph D"}, {"key": "E", "text": "Graph E"}], "correct": "E", "explanation": "Source-keyed answer from book_t1.md (T1-18)."}, "fields": {"stem": "A function f is odd if f(−x) = −f(x) for every x in its domain. Which of the five graphs shown represents an odd function?", "assets_patch": {"figure_required": false, "source_verification_date": "2026-09-29", "figure": "data:image/jpeg;base64,"}}}, {"id": "fc8a09b6-8ecf-5f25-b476-694696e116f0", "source": "ACT 61C Practice, original 2008/09 mathematics test Q59, physical p9; https://www.mymathscloud.com/api/download/modules/University/SAT-ACT/ACT/2008-09.pdf?id=163821380", "review_note": "Recovered all five original graphs. The old textual figure descriptions misplaced the origin and asymptotes; those descriptions have been removed.", "explanation": "An odd function has a graph unchanged by a 180° rotation about the origin: every point (x,y) is paired with (−x,−y). Only graph E has this origin symmetry. A and B are symmetric about the y-axis, D is a line that does not pass through the origin, and C has an offset vertical asymptote, so it is not symmetric about the origin.", "correct": "E", "release": true, "before": {"stem": "A function f is an odd function if and only if f(−x) = −f(x) for every value of x in the domain of f. One of the functions graphed in the standard (x, y) coordinate plane is an odd function. Which one?\n[Figures: A: even W-shaped curve symmetric about the y-axis; B: V-shaped graph (vertex below origin, symmetric about y-axis); C: curve in QI and QIII like y = 1/x; D: line through the origin with positive slope; E: cubic-like curve not through the origin.]", "choices": [{"key": "A", "text": "Graph A"}, {"key": "B", "text": "Graph B"}, {"key": "C", "text": "Graph C"}, {"key": "D", "text": "Graph D"}, {"key": "E", "text": "Graph E"}], "correct": "E", "explanation": "Source-keyed answer from book_t1.md (T1-18)."}, "fields": {"stem": "A function f is odd if f(−x) = −f(x) for every x in its domain. Which of the five graphs shown represents an odd function?", "assets_patch": {"figure_required": false, "source_verification_date": "2026-09-29"}}, "figure_from_id": "7dde08b9-caeb-5620-a1c4-5f141edab444"}, {"id": "171a3aa4-329b-5722-a367-00957e02fa5a", "source": "Texas Education Agency, 2019 released Grade 8 Mathematics Q4, p11; https://tea.texas.gov/student-assessment/staar/released-test-questions/2019-staar-8-math-test.pdf", "review_note": "Original angle markings and vertex order verified, correcting the incomplete textual figure description.", "explanation": "Match the marked angles: R corresponds to D, T to F, and V to B. Following the vertices around the figures gives R↔D, S↔E, T↔F, U↔A, V↔B, W↔C. Therefore ST corresponds to EF and WR corresponds to CD. Corresponding sides have the same ratio, so ST/EF = WR/CD, choice H.", "correct": "H", "release": true, "before": {"stem": "[Figure: Two similar hexagons. Figure I: vertices R, S, T, U, V, W (R marked with double arc, T and V with single arcs). Figure II: vertices A, B, C, D, E, F (F single arc, B single arc, D double arc).]\nFigure I and Figure II are similar figures. Which proportion must be true?", "choices": [{"key": "F", "text": "RS/AB = TU/CD"}, {"key": "G", "text": "TU/AB = UV/AF"}, {"key": "H", "text": "ST/EF = WR/CD"}, {"key": "J", "text": "WV/AB = ST/EF"}], "correct": "H", "explanation": "Source-keyed answer from book_t8.md (T8-20)."}, "fields": {"stem": "Figure I and Figure II are similar. Which proportion must be true?", "assets_patch": {"figure_required": false, "source_verification_date": "2026-09-29", "figure": "data:image/jpeg;base64,"}}}, {"id": "1303e528-b2d3-5e94-a5d9-53f700821027", "source": "Texas Education Agency, 2019 released Grade 8 Mathematics Q4, p11; https://tea.texas.gov/student-assessment/staar/released-test-questions/2019-staar-8-math-test.pdf", "review_note": "Original angle markings and vertex order verified, correcting the incomplete textual figure description.", "explanation": "Match the marked angles: R corresponds to D, T to F, and V to B. Following the vertices around the figures gives R↔D, S↔E, T↔F, U↔A, V↔B, W↔C. Therefore ST corresponds to EF and WR corresponds to CD. Corresponding sides have the same ratio, so ST/EF = WR/CD, choice H.", "correct": "H", "release": true, "before": {"stem": "[Figure: Two similar hexagons. Figure I: vertices R, S, T, U, V, W (R marked with double arc, T and V with single arcs). Figure II: vertices A, B, C, D, E, F (F single arc, B single arc, D double arc).]\nFigure I and Figure II are similar figures. Which proportion must be true?", "choices": [{"key": "F", "text": "RS/AB = TU/CD"}, {"key": "G", "text": "TU/AB = UV/AF"}, {"key": "H", "text": "ST/EF = WR/CD"}, {"key": "J", "text": "WV/AB = ST/EF"}], "correct": "H", "explanation": "Source-keyed answer from book_t8.md (T8-20)."}, "fields": {"stem": "Figure I and Figure II are similar. Which proportion must be true?", "assets_patch": {"figure_required": false, "source_verification_date": "2026-09-29"}}, "figure_from_id": "171a3aa4-329b-5722-a367-00957e02fa5a"}, {"id": "53d1662d-00f9-5e87-bd06-dadb0d7d418b", "source": "Virginia Department of Education, Spring 2008 released Geometry Q42, physical p32; https://www.solpass.org/released_sol_tests/Geometry2008.pdf?section=study-2", "review_note": "Original vertex order visually verified. Preserved the bank’s A–D choice labels; original F–J choices have identical order.", "explanation": "A regular hexagon divides a full turn into six equal 60° steps. A 240° clockwise rotation moves four vertices clockwise: Q → R → S → T → U. Thus Q maps to U, choice C.", "correct": "C", "release": true, "before": {"stem": "[Figure: Regular hexagon inscribed in a circle; vertices labeled (clockwise from top-left): V, Q, R, S, T, U.]\nIn the design, a hexagon is inscribed in a circle. Which point shows the location of Point Q after a 240° clockwise rotation around the center?", "choices": [{"key": "A", "text": "S"}, {"key": "B", "text": "T"}, {"key": "C", "text": "U"}, {"key": "D", "text": "V"}], "correct": "C", "explanation": "Source-keyed answer from book_t10.md (T10-43)."}, "fields": {"stem": "The regular hexagon shown is inscribed in a circle. Which labeled point is the image of Q after a 240° clockwise rotation about the center?", "assets_patch": {"figure_required": false, "source_verification_date": "2026-09-29", "figure": "data:image/jpeg;base64,"}}}, {"id": "f87cef54-c3af-5d4b-85bb-7429f02d45f3", "source": "Virginia Department of Education, Spring 2008 released Geometry Q42, physical p32; https://www.solpass.org/released_sol_tests/Geometry2008.pdf?section=study-2", "review_note": "Original vertex order visually verified. Preserved the bank’s A–D choice labels; original F–J choices have identical order.", "explanation": "A regular hexagon divides a full turn into six equal 60° steps. A 240° clockwise rotation moves four vertices clockwise: Q → R → S → T → U. Thus Q maps to U, choice C.", "correct": "C", "release": true, "before": {"stem": "[Figure: Regular hexagon inscribed in a circle; vertices labeled (clockwise from top-left): V, Q, R, S, T, U.]\nIn the design, a hexagon is inscribed in a circle. Which point shows the location of Point Q after a 240° clockwise rotation around the center?", "choices": [{"key": "A", "text": "S"}, {"key": "B", "text": "T"}, {"key": "C", "text": "U"}, {"key": "D", "text": "V"}], "correct": "C", "explanation": "Source-keyed answer from book_t10.md (T10-43)."}, "fields": {"stem": "The regular hexagon shown is inscribed in a circle. Which labeled point is the image of Q after a 240° clockwise rotation about the center?", "assets_patch": {"figure_required": false, "source_verification_date": "2026-09-29"}}, "figure_from_id": "53d1662d-00f9-5e87-bd06-dadb0d7d418b"}]$payload$::jsonb) LOOP
  SELECT * INTO q FROM public.questions WHERE id=(v->>'id')::uuid FOR UPDATE;
  SELECT * INTO k FROM public.question_keys WHERE question_id=q.id FOR UPDATE;
  IF q.id IS NULL OR k.question_id IS NULL THEN RAISE EXCEPTION 'Missing question/key %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action='question_review_20260929' AND target_id=q.id::text) THEN CONTINUE; END IF;
  IF q.stem IS DISTINCT FROM v->'before'->>'stem' OR q.choices IS DISTINCT FROM v->'before'->'choices'
     OR k.correct IS DISTINCT FROM v->'before'->'correct' OR k.explanation IS DISTINCT FROM v->'before'->>'explanation' THEN
    RAISE EXCEPTION 'Concurrent question change %',q.id;
  END IF;
  IF EXISTS(SELECT 1 FROM public.exams e JOIN public.attempts t ON t.exam_id=e.id
      WHERE q.id=ANY(e.question_ids) AND t.status='in_progress' AND t.deadline_at>now()) THEN
    INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('question_review_deferred_20260929','question',q.id::text,jsonb_build_object('reason','Active exam','proposed',v));
    CONTINUE;
  END IF;
  INSERT INTO public.audit_log(action,target_type,target_id,meta)
  VALUES('question_review_20260929','question',q.id::text,jsonb_build_object('before_question',to_jsonb(q),'before_key',to_jsonb(k),'verification',v-'before'));
  a=coalesce(q.assets,'{}'::jsonb); patch=coalesce(v->'fields','{}'::jsonb);
  IF v ? 'figure_from_id' THEN
   SELECT assets->'figure' INTO f FROM public.questions WHERE id=(v->>'figure_from_id')::uuid;
   IF f IS NULL THEN RAISE EXCEPTION 'Missing verified figure for %',q.id; END IF;
   a=(a-'figure_required')||jsonb_build_object('figure',f,'figure_verified_source',v->>'figure_from_id');
  END IF;
  a=a||coalesce(patch->'assets_patch','{}'::jsonb)||jsonb_build_object(
    'answer_review','2026-09-29-independent-solution-and-source-check','verification_source',v->>'source',
    'verification_note',v->>'review_note','content_audit','2026-09-29-all-bank-structural-audit');
  IF coalesce((v->>'release')::boolean,false) THEN
   a=(a-'release_hold_reason')||jsonb_build_object('verified_release','2026-09-29-independent-solution-and-source-check');
  ELSIF v ? 'duplicate_of' THEN
   a=a||jsonb_build_object('release_hold_reason','Duplicate of reviewed question','duplicate_of',v->>'duplicate_of');
  END IF;
  UPDATE public.questions SET stem=coalesce(patch->>'stem',q.stem),choices=coalesce(patch->'choices',q.choices),
   topic=coalesce(patch->>'topic',q.topic),type=coalesce(patch->>'type',q.type),assets=a WHERE id=q.id;
  UPDATE public.question_keys SET correct=coalesce(v->'correct',k.correct),explanation=coalesce(v->>'explanation',k.explanation) WHERE question_id=q.id;
  IF v->>'source_question_id' IS NOT NULL THEN
   INSERT INTO public.audit_log(action,target_type,target_id,meta)
   SELECT 'staged_question_review_20260929','question_bank',b.question_id,jsonb_build_object('before',to_jsonb(b)) FROM public.question_bank b WHERE b.question_id=v->>'source_question_id';
   UPDATE public.question_bank SET stem_text=coalesce(patch->>'stem',q.stem),choices=coalesce(patch->'choices',q.choices),
    answer_key=coalesce(v->'correct',k.correct)#>>'{}',answer_explanation=coalesce(v->>'explanation',k.explanation),
    answer_key_status='independently_verified',needs_review=false,review_reasons=jsonb_build_array(v->>'review_note')
   WHERE question_id=v->>'source_question_id' AND coalesce((v->>'release')::boolean,false);
  END IF;
 END LOOP;
END;
$review$;
SELECT jsonb_build_object('applied',(SELECT count(*) FROM public.audit_log WHERE action='question_review_20260929'),
 'deferred',(SELECT count(*) FROM public.audit_log WHERE action='question_review_deferred_20260929')) AS result;
